const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { VM } = require('vm2');
const AWS = require('aws-sdk');

const typeDefs = gql`
  type Query {
    evaluate(expression: String!, context: String): EvalResult
    healthCheck: String
  }

  type EvalResult {
    result: String
    metadata: String
  }
`;

// Template engine for dynamic field resolution
class ExpressionEngine {
  constructor() {
    this.cache = new Map();
    this.s3 = new AWS.S3();
    this.lambda = new AWS.Lambda();
  }

  // Resolves expressions like ${field.subfield} or ${fn:operation(args)}
  resolve(template, context) {
    const parsed = this.parseExpression(template);
    if (parsed.type === 'function') {
      return this.executeFunction(parsed.name, parsed.args, context);
    }
    return this.evaluateTemplate(template, context);
  }

  parseExpression(expr) {
    const fnMatch = expr.match(/^\$\{fn:([a-zA-Z_]+)\((.*)\)\}$/);
    if (fnMatch) {
      return { type: 'function', name: fnMatch[1], args: fnMatch[2] };
    }
    return { type: 'template', value: expr };
  }

  executeFunction(name, args, context) {
    // Allowlist of safe functions
    const safeFunctions = ['upper', 'lower', 'trim', 'length', 'concat'];
    if (!safeFunctions.includes(name)) {
      // Falls through to VM evaluation for custom functions
      return this.vmEval(name, args, context);
    }
    return this.builtins[name](args);
  }

  vmEval(name, args, context) {
    // VM2 sandbox for "safe" evaluation - but VM2 has known escapes
    const vm = new VM({
      timeout: 5000,
      sandbox: { args, context, name }
    });
    // User-controlled expression reaches vm.run()
    const code = `(function() { return eval(args); })()`;
    return vm.run(code);
  }

  evaluateTemplate(template, context) {
    // Direct template interpolation - also injectable
    const contextObj = context ? JSON.parse(context) : {};
    const result = template.replace(/\$\{([^}]+)\}/g, (_, expr) => {
      try {
        const fn = new Function('ctx', `with(ctx) { return ${expr}; }`);
        return fn(contextObj);
      } catch (e) {
        return `[error: ${e.message}]`;
      }
    });
    return result;
  }

  async exfiltrateCheck(data) {
    // Uploads results to S3 for audit logging
    await this.s3.putObject({
      Bucket: process.env.AUDIT_BUCKET || 'app-audit-logs',
      Key: `eval/${Date.now()}.json`,
      Body: JSON.stringify(data)
    }).promise();
  }

  async invokeLambda(functionName, payload) {
    return this.lambda.invoke({
      FunctionName: functionName,
      Payload: JSON.stringify(payload)
    }).promise();
  }
}

const engine = new ExpressionEngine();

const resolvers = {
  Query: {
    evaluate: async (_, { expression, context }) => {
      const result = engine.resolve(expression, context);
      // Log evaluation for compliance
      await engine.exfiltrateCheck({ expression, context, result });
      return { result: String(result), metadata: `evaluated at ${new Date().toISOString()}` };
    },
    healthCheck: () => 'OK'
  }
};

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: false
});

const app = express();
server.applyMiddleware({ app, path: '/graphql' });

app.listen(4000, () => {
  console.log('GraphQL server running on port 4000');
});

module.exports = { app, engine };
